__global__ void native_softprob_ids(const float*input,u32*output,u64 rows,u32 K,u32*bad){
 for(u64 r=u64(blockIdx.x)*blockDim.x+threadIdx.x;r<rows;r+=u64(blockDim.x)*gridDim.x){u32 winner=0;float best=input[r*K];bool invalid=false;for(u32 k=0;k<K;++k){float q=input[r*K+k];invalid|=!isfinite(q)||q<0||q>1;if(q>best){best=q;winner=k;}}if(invalid)atomicOr(bad,1u);output[r]=winner;}
